parameters.jsCode:
// The form trigger names the binary property after the field label, which
// changes if you rename the field. Grab whatever came in and call it `data`.
const out = [];

for (const item of $input.all()) {
  const keys = Object.keys(item.binary || {});
  if (!keys.length) {
    throw new Error('No file arrived from the form. Check the upload field is set to type "File".');
  }
  out.push({
    json: item.json,
    binary: { data: item.binary[keys[0]] },
  });
}

return out;

parameters.text:
=Build a teaching pack from this paper.

SESSION LENGTH: {{ $json.sessionMinutes }} minutes
STUDENT LEVEL: {{ $json.studentLevel }}
TUTOR'S REQUESTED FOCUS: {{ $json.focus }}

Honour the requested focus if one is given — it should visibly shape the abstract question, the key ideas you select, and the slide arc. If none is given, choose the angle with the most teaching potential.

=== FULL TEXT OF THE PAPER ===

{{ $json.paperText }}

=== END OF PAPER ===

parameters.inputSchema:
{
