    },
    "whyItMatters": {
      "type": "string",
      "description": "Why this paper is worth a whole session"
    },
    "abstractQuestion": {
      "type": "string",
      "description": "The unanswerable opening question \u2014 deceptively simple, deeply complex, resolvable through guided inquiry"
    },
    "abstractQuestionNotes": {
      "type": "string",
      "description": "How to run the opener, staged: how to pose it, the wrong answers students will offer, the pivot from each toward the paper, and what counts as resolution"
    },
    "paperAnalysis": {
      "type": "object",
      "properties": {
        "problem": {
          "type": "string",
          "description": "The specific gap, question or challenge the work addresses, and why it was open"
        },
        "argument": {
          "type": "string",
          "description": "The paper's chain of reasoning reconstructed step by step \u2014 premise, calculation, inference, conclusion \u2014 with the key number at each link. A tutor should be able to deliver the whole argument from this field alone."
        },
        "methods": {
          "type": "string",
          "description": "Techniques, models, assays, instruments, statistical approach \u2014 including inputs and assumptions, enough that a tutor can explain HOW and defend the choices"
