          "minutes",
          "what"
        ]
      }
    },
    "slidePlan": {
      "type": "object",
      "properties": {
        "narrativeArc": {
          "type": "string"
        },
        "designNotes": {
          "type": "string"
        },
        "slides": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "number": {
                "type": "number"
              },
              "title": {
                "type": "string"
              },
              "purpose": {
                "type": "string",
                "description": "One line: the job this slide does"
              },
              "bullets": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "3-5 on-screen fragments"
              },
              "visual": {
                "type": "string",
                "description": "The image, chart or diagram that carries the slide; for rebuilt figures, name the figure and say how to simplify it"
              },
              "talkTrack": {
                "type": "string",
                "description": "What the tutor says while this slide is up"
              }
            },
            "required": [
              "number",
              "title",
              "purpose",
              "bullets",
              "visual",
              "talkTrack"
            ]
          }
        }
      },
      "required": [
        "narrativeArc",
        "designNotes",
        "slides"
      ]
    },
    "furtherReading": {
      "type": "array",
      "description": "Papers cited in this paper worth reading next, each citation as printed in the reference list. Empty array if the reference list is not visible.",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "paperTitle",
    "citation",
    "domain",
    "tldr",
    "whyItMatters",
    "abstractQuestion",
    "abstractQuestionNotes",
    "paperAnalysis",
    "keyIdeas",
    "discussionPoints",
    "misconceptions",
    "glossary",
    "sessionFlow",
    "slidePlan",
    "furtherReading"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Render the structured teaching pack as print-ready HTML.
// Gotenberg turns this into the PDF; all layout lives in the CSS below.

const src  = $input.first().json;
const o    = src.output ?? src;
const form = $('Upload a paper').first().json;

/* ---------- helpers ---------- */
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const inline = (s) => esc(s)
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/(^|[\s(])\*([^*]+?)\*/g, '$1<em>$2</em>');

const rich = (s) => {
  const t = String(s ?? '').trim();
  if (!t) return '<p class="muted">Not stated in the paper.</p>';
  return t.split(/\n{2,}/)
          .map(p => `<p>${inline(p.replace(/\n/g, ' '))}</p>`)
          .join('');
};

const arr = (a) => Array.isArray(a) ? a : [];

// Labelled meta line that renders nothing when the field is empty,
// so packs generated by the old schema don't print blank labels.
const metaRow = (label, val, cls = 'kmeta') => {
  const t = String(val ?? '').trim();
  if (!t) return '';
  return `<p class="${cls}"><span class="label">${esc(label)}</span>${inline(t)}</p>`;
};

/* ---------- sections ---------- */
const analysis = o.paperAnalysis ?? {};
const analysisRows = [
  ['The problem',   analysis.problem],
  ['The argument',  analysis.argument],
  ['Methods',       analysis.methods],
  ['Results',       analysis.results],
  ['Findings',      analysis.findings],
  ['Contribution',  analysis.contributions],
  ['Limitations',   analysis.limitations],
  ['Where it goes', analysis.futureWork],
].map(([label, body]) => `
  <div class="row">
    <div class="row-label">${esc(label)}</div>
    <div class="row-body">${rich(body)}</div>
  </div>`).join('');

const keyIdeas = arr(o.keyIdeas).map((k, i) => `
  <div class="card">
    <h3><span class="num">${i + 1}</span>${esc(k.concept)}</h3>
    ${rich(k.explanation)}
    ${metaRow('In this paper', k.inThisPaper)}
    ${metaRow('Where students struggle', k.whereStudentsStruggle)}
    <p class="angle"><span class="label">Teaching angle</span>${inline(k.teachingAngle)}</p>
    ${metaRow('Check', k.checkForUnderstanding, 'kmeta check')}
  </div>`).join('');

const discussion = arr(o.discussionPoints).map((d, i) => `
  <div class="card q">
    <div class="q-head">
      <span class="q-num">Q${i + 1}</span>
      <span class="tag tag-${esc(String(d.level ?? 'core')).replace(/[^a-z-]/gi, '')}">${esc(d.level)}</span>
    </div>
    <p class="q-text">${inline(d.question)}</p>
    <p class="q-meta"><span class="label">Purpose</span>${inline(d.purpose)}</p>
    <p class="q-meta"><span class="label">Where it leads</span>${inline(d.whereItLeads)}</p>
  </div>`).join('');

const misconceptions = arr(o.misconceptions).map(m => `
  <div class="card mis">
    <p class="mis-claim">${inline(m.misconception)}</p>
    <p class="mis-fix">${inline(m.correction)}</p>
  </div>`).join('');

const glossary = arr(o.glossary).map(g => `
  <div class="gloss">
    <dt>${esc(g.term)}</dt>
    <dd>${inline(g.definition)}</dd>
  </div>`).join('');

const flow = arr(o.sessionFlow).map(s => `
  <tr>
    <td class="mins">${esc(s.minutes)} min</td>
    <td class="seg">${esc(s.segment)}</td>
    <td>${inline(s.what)}</td>
  </tr>`).join('');

const slides = arr(o.slidePlan?.slides).map(s => `
  <div class="card slide">
    <div class="slide-head">
      <span class="slide-num">${esc(s.number)}</span>
      <span class="slide-title">${esc(s.title)}</span>
    </div>
    <p class="slide-purpose">${inline(s.purpose)}</p>
    <ul>${arr(s.bullets).map(b => `<li>${inline(b)}</li>`).join('')}</ul>
    <p class="slide-meta"><span class="label">Visual</span>${inline(s.visual)}</p>
    <p class="slide-meta"><span class="label">Talk track</span>${inline(s.talkTrack)}</p>
  </div>`).join('');

const reading = arr(o.furtherReading).length
  ? `<ul class="reading">${arr(o.furtherReading).map(r => `<li>${inline(r)}</li>`).join('')}</ul>`
  : '<p class="muted">No reference list was visible in the uploaded PDF.</p>';

/* ---------- document ---------- */
const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<style>
  @page { size: A4; margin: 17mm 15mm 16mm 15mm; }
  * { box-sizing: border-box; }
  body { margin:0; color:#161a1d; font:9.8pt/1.45 Georgia,"Liberation Serif","Times New Roman",serif;
         -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  h1,h2,h3,.label,.tag,.meta,.mins,.seg,th,.q-num,.slide-num,.num
        { font-family:"Helvetica Neue",Helvetica,Arial,"Liberation Sans",sans-serif; }

  h1 { font-size:18pt; line-height:1.16; letter-spacing:-0.015em; margin:0 0 6px; }
  .meta { font-size:8.5pt; color:#5c6771; line-height:1.45; margin:0 0 13px; }
  .meta strong { color:#161a1d; font-weight:600; }

  h2 { font-size:9.5pt; text-transform:uppercase; letter-spacing:.11em; color:#1b3f5c;
       margin:20px 0 8px; padding-bottom:4px; border-bottom:1.5px solid #1b3f5c; }
  h3 { font-size:10.5pt; margin:0 0 5px; }
  p  { margin:0 0 6px; orphans:3; widows:3; }
  .muted { color:#7d868e; font-style:italic; }
  .label { display:block; font-size:7pt; text-transform:uppercase; letter-spacing:.1em;
           color:#8a6a3d; margin-bottom:2px; font-weight:600; }

  .tldr { background:#f5f2eb; border-left:3px solid #a2542f; padding:9px 13px; margin:0 0 10px; }
  .tldr p:last-child { margin-bottom:0; }
  .tldr .label { color:#a2542f; }

  .aq { border:1px solid #1b3f5c; padding:10px 13px; margin:0 0 4px; background:#f7f9fb; }
  .aq .label { color:#1b3f5c; }
  .aq-q { font-size:12.5pt; line-height:1.32; margin:0 0 7px; }

  .row { display:flex; gap:13px; margin-bottom:9px; }
  .row-label { flex:0 0 82px; font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;
               font-size:8pt; text-transform:uppercase; letter-spacing:.07em;
               color:#1b3f5c; font-weight:600; padding-top:2px; }
  .row-body { flex:1; }
  .row-body p:last-child { margin-bottom:0; }

  .card { break-inside:avoid; page-break-inside:avoid; margin-bottom:11px; }
  .num { display:inline-block; width:17px; color:#a2542f; font-weight:700; }
  .angle { font-size:9pt; color:#3d454c; border-left:2px solid #ddd6c8; padding-left:9px; margin-top:4px; }
  .kmeta { font-size:9pt; color:#41494f; margin:4px 0 3px; }
  .kmeta .label { display:inline; margin-right:6px; }
  .kmeta.check { border-left:2px solid #1b3f5c; padding-left:9px; }

  .q { border-bottom:1px solid #e6e3dc; padding-bottom:6px; }
  .q-head { margin-bottom:3px; }
  .q-num { font-size:8pt; font-weight:700; color:#1b3f5c; letter-spacing:.05em; margin-right:8px; }
  .tag { font-size:6.5pt; text-transform:uppercase; letter-spacing:.09em; padding:2px 6px;
         border-radius:2px; font-weight:600; }
  .tag-warmup,.tag-warm-up { background:#e8efe6; color:#3f6b39; }
  .tag-core   { background:#e6edf3; color:#1b3f5c; }
  .tag-stretch{ background:#f6e8e2; color:#9c4a26; }
  .q-text { font-size:10.5pt; margin-bottom:4px; }
  .q-meta { font-size:9pt; color:#41494f; margin-bottom:3px; }
  .q-meta .label { display:inline; margin-right:6px; }

  .mis { border-left:3px solid #c8b8a0; padding-left:11px; }
  .mis-claim { font-style:italic; color:#8a5c34; margin-bottom:4px; }
  .mis-fix { font-size:10pt; margin-bottom:0; }

  .gloss { break-inside:avoid; margin-bottom:4px; }
  .gloss dt { font-weight:700; font-size:10pt; display:inline; }
  .gloss dd { display:inline; margin:0; font-size:10pt; color:#3d454c; }
  .gloss dt::after { content:" — "; color:#9aa3aa; font-weight:400; }

  table.flow { width:100%; border-collapse:collapse; font-size:9.5pt; }
  table.flow td { padding:6px 8px 6px 0; border-bottom:1px solid #eceae4; vertical-align:top; }
  .mins { white-space:nowrap; font-size:8.5pt; font-weight:700; color:#a2542f; width:50px; }
  .seg  { white-space:nowrap; font-size:9pt; font-weight:600; width:120px; }

  .break { page-break-before:always; }
  .slide { border:1px solid #e6e3dc; padding:9px 12px; }
  .slide-head { display:flex; align-items:baseline; gap:9px; margin-bottom:3px; }
  .slide-num { background:#1b3f5c; color:#fff; font-size:8pt; font-weight:700;
               padding:2px 7px; border-radius:2px; }
  .slide-title { font-size:11pt; font-weight:700; }
  .slide-purpose { font-size:9pt; color:#6b747c; font-style:italic; margin-bottom:6px; }
  .slide ul { margin:0 0 7px; padding-left:17px; }
  .slide li { font-size:10pt; margin-bottom:2px; }
  .slide-meta { font-size:9pt; color:#41494f; margin-bottom:3px; }
  .slide-meta .label { display:inline; margin-right:6px; }

  .reading li { font-size:9.5pt; margin-bottom:4px; }
  .foot { margin-top:26px; padding-top:8px; border-top:1px solid #e6e3dc;
          font-size:7.5pt; color:#8a929a; font-family:"Helvetica Neue",Helvetica,Arial,sans-serif; }
</style></head><body>

<h1>${esc(o.paperTitle)}</h1>
<p class="meta">
  <strong>${esc(o.citation)}</strong><br>
  ${esc(o.domain)} &nbsp;·&nbsp; ${esc(form['Session length (minutes)'])}-minute session &nbsp;·&nbsp; ${esc(form['Student level'])}
</p>

<div class="tldr">
  <span class="label">In one sentence</span>
  <p>${inline(o.tldr)}</p>
</div>

<h2>Why this paper earns a session</h2>
${rich(o.whyItMatters)}

<h2>The opening question</h2>
<div class="aq">
  <span class="label">Cold-call opener</span>
  <p class="aq-q">${inline(o.abstractQuestion)}</p>
  ${rich(o.abstractQuestionNotes)}
</div>

<h2>The paper</h2>
${analysisRows}

<h2>Key ideas</h2>
${keyIdeas}

<h2>Discussion points</h2>
${discussion}

<h2>Misconceptions to pre-empt</h2>
${misconceptions}

<h2>Glossary</h2>
<dl>${glossary}</dl>

<div class="break"></div>

<h1>Delivery plan</h1>
<p class="meta">${esc(form['Session length (minutes)'])} minutes &nbsp;·&nbsp; ${arr(o.slidePlan?.slides).length} slides &nbsp;·&nbsp; ${esc(o.paperTitle)}</p>

<h2>Running order</h2>
<table class="flow"><tbody>${flow}</tbody></table>

<h2>Narrative arc of the deck</h2>
${rich(o.slidePlan?.narrativeArc)}

<h2>Design notes</h2>
${rich(o.slidePlan?.designNotes)}

<h2>Slide by slide</h2>
${slides}

<h2>Further reading</h2>
${reading}

<p class="foot">Generated from the uploaded PDF. Every claim traces to the paper — verify figures and statistics against the original before teaching.</p>

</body></html>`;

/* ---------- filename + covering email ---------- */
const safeTitle = String(o.paperTitle ?? 'Paper')
  .replace(/[\\/:*?"<>|]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 70);

const emailBody = `
<div style="font:15px/1.6 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#161a1d;max-width:620px">
  <p style="margin:0 0 14px">Teaching pack attached for <strong>${esc(o.paperTitle)}</strong>.</p>
  <p style="margin:0 0 6px;font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#8a6a3d">Opening question</p>
  <p style="margin:0 0 16px;font-size:17px;line-height:1.4">${inline(o.abstractQuestion)}</p>
  <p style="margin:0 0 6px;font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#8a6a3d">In one sentence</p>
  <p style="margin:0 0 18px">${inline(o.tldr)}</p>
  <p style="margin:0;color:#6b747c;font-size:13px">
    ${arr(o.discussionPoints).length} discussion points · ${arr(o.keyIdeas).length} key ideas ·
    ${arr(o.slidePlan?.slides).length}-slide plan
  </p>
</div>`;

return [{
  json: {
    html,
    fileName: `Teaching Pack - ${safeTitle}.pdf`,
    subject: `Teaching pack: ${o.paperTitle}`,
    emailBody,
  },
}];

// Attach a human filename to the PDF that came back from Gotenberg,
// and carry the subject / covering note through to the email node.
const item = $input.first();
const meta = $('Build report HTML').first().json;

if (!item.binary?.data) {
  throw new Error('Gotenberg returned no file. Check it is reachable at the URL in the Render PDF node.');
}

item.binary.data.fileName      = meta.fileName;
item.binary.data.fileExtension = 'pdf';
item.binary.data.mimeType      = 'application/pdf';

item.json = { subject: meta.subject, emailBody: meta.emailBody, fileName: meta.fileName };

return [item];
